style.css:
@-moz-document domain("youtube.com") {
/* 1. FONDO ULTRA OSCURO (ESTILO OLED/NEGRO PURO) */
    html, 
    html[dark],
    ytd-app, 
    #page-manager, 
    ytd-masthead,
    #contentContainer,
    ytd-playlist-panel-renderer {
        background-color: #000000 !important;
        --yt-spec-base-background: #000000 !important;
        --yt-spec-raised-background: #0a0a0a !important;
    }

    /* 2. DETALLES EN ROSA FUCSIA NEÓN */
    .ytp-play-progress, 
    .ytp-volume-slider-handle::before,
    .ytp-scrubber-button {
        background: #ff007f !important;
    }

    /* Botón de Suscribirse */
    ytd-subscribe-button-renderer version-cards-v2 .yt-spec-button-shape-next--filled {
        background-color: #ff007f !important;
        color: #000000 !important;
        font-weight: bold !important;
    }

    /* Enlaces y hashtags */
    a.yt-simple-endpoint.yt-formatted-string,
    .yt-core-attributed-string__link {
        color: #ff007f !important;
    }

    /* 3. CAMBIAR COLOR DE TEXTOS Y TÍTULOS */
    #video-title, 
    h1.ytd-watch-metadata,
    .title.ytd-video-primary-info-renderer,
    #title.ytd-rich-grid-media,
    span.yt-core-attributed-string {
        color: #ffffff !important;
    }

    #metadata-line span,
    #byline.ytd-video-meta-block,
    .yt-core-attributed-string--text-alignment-leading {
        color: #e0e0e0 !important;
    }

    /* 4. BORDES EN ROSA */
    ytd-thumbnail img,
    #player-container-inner {
        border: 2px solid #ff007f !important;
        box-shadow: 0px 0px 10px rgba(255, 0, 127, 0.4) !important;
    }

    ytd-author-comment-badge-renderer {
        background-color: #ff007f !important;
    }
}
